function checkWallet(){
  const phone=document.getElementById('wallet-input').value.trim();
  const el=document.getElementById('wallet-result');
  const ee=document.getElementById('earn-result');
  if(!phone){el.style.display='block';el.innerHTML='<div style="color:#d32f2f;font-size:12px">Enter your phone number</div>';return}
  el.style.display='block';
  el.innerHTML='<div style="color:#666;font-size:12px">Loading your wallet...</div>';
  fetch('/api/economy/balance?phone='+encodeURIComponent(phone))
    .then(r=>r.json())
    .then(d=>{
      if(!d.success){el.innerHTML='<div style="color:#d32f2f;font-size:12px">'+(d.error||'Wallet not found')+'</div>';return}
      const fmtN=n=>Number(n).toLocaleString('en-NG',{maximumFractionDigits:0});
      el.innerHTML='<div style="padding:10px;background:#f8f9fa;border-radius:8px">'+
        '<div style="display:flex;justify-content:space-between;align-items:center">'+
        '<div><div style="font-size:11px;color:#999">HARZcoin (L1)</div><div style="font-size:22px;font-weight:800;color:#0a3d2e">'+Number(d.balance_harz).toLocaleString('en',{maximumFractionDigits:2})+' HARZ</div></div>'+
        '<div style="text-align:right"><div style="font-size:11px;color:#999">Value</div><div style="font-size:16px;font-weight:700;color:#0a3d2e">\u20A6'+fmtN(d.balance_ngn)+'</div><div style="font-size:10px;color:#999">$'+Number(d.balance_usd).toLocaleString()+'</div></div>'+
        '</div>'+
        '<div style="margin-top:8px;padding-top:8px;border-top:1px solid #e0e0e0;font-size:10px;color:#999">Price: $'+d.harz_price_usd+' \u2022 Rate: \u20A6'+fmtN(d.ngn_rate)+'/USD \u2022 '+d.price_source+' \u2022 Chain '+(d.chain_live?'LIVE':'OFFLINE')+' @ block '+fmtN(d.chain_height)+'</div>'+
        '</div>';
      ee.style.display='block';
      ee.innerHTML='<div style="margin-top:8px;padding:8px;background:#fff8e1;border-radius:8px;font-size:11px;color:#795548">'+
        '\u20A1 Daily Earn: '+(d.earn.claimed_today?'<b>Claimed today</b>':'<b>Available now!</b>')+' \u2022 Streak: '+d.earn.streak+' day(s) \u2022 Pending: '+Number(d.earn.pending).toLocaleString()+' HARZ (settles to L1 weekly)'+
        '</div>';
      try{localStorage.setItem('harzsuperapp_bal:'+phone,JSON.stringify({t:Date.now(),h:el.innerHTML}))}catch(x){}
    })
    .catch(()=>{var raw=null;try{raw=JSON.parse(localStorage.getItem('harzsuperapp_bal:'+phone)||'null')}catch(x){}if(raw){el.innerHTML=tagHTML('cached',Date.now()-raw.t)+'<div style="font-size:9px;color:#999">OFFLINE \u2014 wallet from cache</div>'+raw.h}else{el.innerHTML='<div style="color:#d32f2f;font-size:12px">OFFLINE \u2014 wallet needs HARZ Chain when online. Try again once connected.</div>'}});
}
function claimEarn(){
  const phone=document.getElementById('wallet-input').value.trim();
  const ee=document.getElementById('earn-result');
  if(!phone){ee.style.display='block';ee.innerHTML='<div style="color:#d32f2f;font-size:12px">Enter your phone number first</div>';return}
  ee.style.display='block';
  ee.innerHTML='<div style="color:#666;font-size:12px">Claiming...</div>';
  fetch('/api/economy/earn',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone:phone})})
    .then(r=>r.json())
    .then(d=>{
      if(!d.success){ee.innerHTML='<div style="padding:8px;background:#fff3e0;border-radius:8px;font-size:11px;color:#e65100">'+(d.error||'Could not claim')+' \u2022 Streak: '+(d.streak||0)+' \u2022 Pending: '+Number(d.pending||0).toLocaleString()+' HARZ</div>';return}
      ee.innerHTML='<div style="padding:8px;background:#e8f5e9;border-radius:8px;font-size:11px;color:#0a3d2e">\u2713 Claimed <b>'+Number(d.reward).toLocaleString()+' HARZ</b> \u2022 Streak: '+d.streak+' day(s) \u2022 Pending total: '+Number(d.pending).toLocaleString()+' HARZ</div>';
      checkWallet();
    })
    .catch(()=>{ee.innerHTML='<div style="color:#d32f2f;font-size:12px">OFFLINE \u2014 claims need connection. Your streak is safe; try again when online.</div>'});
}

